def test_cast_from_strips_extra_and_honours_precedence():
    address = types.Address(StreetAddress="123 Sesame Street", City="New York", State="NY")
    # Second arg carries a field Address doesn't define; cast_from must drop it.
    cast = types.Address.cast_from(address, {"City": "Buffalo", "NotAnAddressField": "x"})
    assert isinstance(cast, types.Address)
    assert cast.StreetAddress == "123 Sesame Street"
    assert cast.City == "New York"  # first arg wins
    assert not hasattr(cast, "NotAnAddressField")


def test_generic_round_trip_via_factory():
    fixture = Path(__file__).parent / "fixtures" / "scheduling_modification.json"
    sample = loads(fixture.read_text())

    strict = redox_object_factory(sample)
    assert isinstance(strict, Modification)

    generic = from_redox_to_generic(strict)
    assert isinstance(generic, GenericScheduling.Modification)

    # generic -> proper Redox -> dict should match the original strict dump.
    assert generic.to_redox().model_dump() == strict.model_dump()


